//! Contract test: Rust reads the files the real Python writers produce.
//!
//! `tests/fixtures/*.jsonl` were generated by `shield.agent_core.router.EventRouter` writing a real
//! `EventLog` row, and by `EnforcementOutcome.to_dict()` through `LocalOutcomeLog`. If Python's
//! shape changes, `tests/test_device_contract.py` fails on the Python side and these fixtures must
//! be regenerated; this file then proves the Rust reader still understands them.

use device_core::{frozen_processes, overview, read_jsonl_tail, summarize_decision, Paths, ProcState};
use std::path::{Path, PathBuf};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures")
}

#[test]
fn the_real_decision_row_is_understood() {
    let t = read_jsonl_tail(&fixtures().join("decisions.jsonl"), 10).unwrap();
    assert_eq!(t.malformed, 0);
    let row = summarize_decision(&t.records[0]);
    assert_eq!(row.action, "contain");
    assert_eq!(row.class, "process_activity");
    assert_eq!(row.severity, "low");
    assert!(!row.time.is_empty());
}

#[test]
fn the_real_outcomes_derive_the_right_frozen_list() {
    let t = read_jsonl_tail(&fixtures().join("outcomes.jsonl"), usize::MAX).unwrap();
    assert_eq!(t.records.len(), 3);
    let no_proc = fixtures().join("no-proc-here");

    // Freeze alone: pid 4242 is listed, with the router's own measured latency.
    let frozen = frozen_processes(&t.records[..1], &no_proc);
    assert_eq!(frozen.len(), 1);
    assert_eq!(frozen[0].pid, 4242);
    assert_eq!(frozen[0].handle_to_contain_ms, Some(0.233));
    assert_eq!(frozen[0].state, ProcState::Unknown); // no /proc here: reported as unverifiable

    // Freeze, a failed attempt on another pid, then the operator's resume naming the freeze:
    // nothing remains frozen, and the failed attempt never appeared.
    assert!(frozen_processes(&t.records, &no_proc).is_empty());
}

#[test]
fn the_overview_joins_both_real_files() {
    let paths = Paths::resolve(Some(fixtures().to_str().unwrap()), None).unwrap();
    let o = overview(&paths, &fixtures().join("no-proc-here"), 20);
    assert!(o.frozen.is_empty());
    assert_eq!(o.recent_decisions.len(), 1);
    assert!(o.notes.is_empty(), "real, well-formed logs must produce no warnings: {:?}", o.notes);
}
